14	func main() {
15		command := "demo"
16		if len(os.Args) > 1 {
17			command = os.Args[1]
18		}
19		switch command {
20		case "demo":
21			runDemo()
22		case "version":
23			fmt.Println("indexroom 0.1.0")
24		case "register":
25			os.Exit(runRegister())
26		case "help", "-h", "--help":
27			usage()
28		default:
29			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
30			usage()
31			os.Exit(2)
32		}
33	}
34	
35	func usage() {
36		fmt.Println("usage: indexroom [demo|version|register|help]")
37		fmt.Println()
38		fmt.Println("register reads service registrations as JSON from standard input:")
39		fmt.Println(`  {"requests":[{"service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"host:8080"}]}]}`)
40		fmt.Println("Each request fully replaces the service's instance list. New services")
41		fmt.Println("require expectedRevision 0; existing services require the current revision.")
42		fmt.Println("Exit status is 0 only when every registration succeeds.")
43	}
44	
45	// registerInstance is one instance in the final service list.
46	type registerInstance struct {
47		ID      string `json:"id"`
48		Address string `json:"address"`
49	}
50	
51	// registerService is one service in the final service list.
52	type registerService struct {
53		Service   string             `json:"service"`
54		Revision  int                `json:"revision"`
55		Instances []registerInstance `json:"instances"`
56	}
57	
58	// registerResult is the per-item outcome.
